outputs.rawYaml:
id: adapterremoval_settings
name: Trimming and collapsing statistics
description: >-
  Read pairs in, mates merged, reads discarded and sequences retained, from an
  AdapterRemoval .settings report. The counts balance exactly, which is what
  lets a read-fate flow be drawn from them without apportioning anything. One
  row per report, so a pipeline that trims per lane gets one row per lane.
find:
  path_glob: "**/*.settings"
recipe: adapterremoval/settings.py
fixture: settings.tsv
renders_as:
  - { id: collapse_vs_length, component: advanced_viz, kind: scatter_xy,
      roles: {x: average_retained_length, y: collapse_rate, label: sample, color: sample, size: retained_reads} }
  - { component: figure, visu_type: bar, dict_kwargs: {x: sample, y: retained_reads, color: sample, title: Sequences retained per report} }
  - { component: card, column: total_read_pairs, aggregation: sum, secondary_layout: attrition, attrition_cols: [well_aligned_read_pairs, collapsed_pairs] }
  - { component: card, column: collapse_rate, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: average_retained_length, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: discard_rate, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: retained_reads, aggregation: sum, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: table }

id: ampcombi_clusters
name: Peptide clusters
mode: amp/clusters
description: >-
  One row per sequence cluster AMPcombi built across the run with MMseqs2, with
  the representative sequence header, the sample that contributed it and the
  number of members.
find: { path_glob: "**/ampcombi2/Ampcombi_summary_cluster_representative_seq.tsv" }
recipe: ampcombi/clusters.py
fixture: clusters.tsv
renders_as:
  - { component: figure, visu_type: histogram, dict_kwargs: {x: members, title: Cluster size distribution} }
  - { component: card, column: members, aggregation: max, secondary_layout: top_n, breakdown_col: sample, top_n_count: 4 }
  - { component: card, column: members, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: table }

id: anota2seq_regulation
name: Translational regulation mode per gene
mode: translation/regulation
description: >-
  One row per contrast and gene with the four anota2seq analyses side by side
  and one regulatory mode: translation, buffering, mRNA abundance or not
  regulated, assigned with anota2seq's default selection thresholds.
find: { path_glob: "**/*.anota2seq.results.tsv" }
recipe: anota2seq/regulation.py
fixture: regulation.tsv
renders_as:
  # The anota2seq fold-change plane: total mRNA change on x, ribosome-bound
  # mRNA change on y. Translation-regulated genes leave the diagonal, buffered
  # genes lie flat along x, mRNA-abundance genes ride the diagonal.
  - id: fold_change_plane
    component: advanced_viz
    kind: scatter_xy
    roles: { x: total_mrna_lfc, y: translated_mrna_lfc, label: gene_name, color: regulation_mode }
  - id: translation_volcano
    component: advanced_viz
    kind: volcano
    roles: { feature_id: gene_name, effect_size: translation_effect, significance: translation_padj, category: regulation_mode }
  - id: gene_record
    component: advanced_viz
    kind: record_card
    roles: { id: gene_id, title: gene_name }
  - { component: card, column: gene_id, aggregation: nunique, secondary_layout: donut, breakdown_col: regulation_mode }
  - { component: card, column: translation_effect, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: total_mrna_lfc, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: translated_mrna_lfc, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: interactive, interactive_type: MultiSelect, column_name: regulation_mode }
  - { component: table, row_selection_enabled: true, row_selection_column: gene_id }

id: anota2seq_results
name: anota2seq results per analysis
mode: translation/differential
description: >-
  The four anota2seq analyses of every contrast stacked in one table: change in
  ribosome-bound mRNA, change in total mRNA, the translation effect (ribosome
  association not explained by mRNA level) and buffering, each with its effect,
  RVM p-value, adjusted p-value and anota2seq's default significance call.
find: { path_glob: "**/*.anota2seq.results.tsv" }
recipe: anota2seq/results.py
fixture: results.tsv
renders_as:
  - id: analysis_volcano
    component: advanced_viz
    kind: volcano
    roles: { feature_id: gene_name, effect_size: effect, significance: padj, category: direction }
  - { component: card, column: gene_id, aggregation: nunique, secondary_layout: donut, breakdown_col: direction }
  - { component: card, column: effect, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: interactive, interactive_type: Select, column_name: analysis }
  - { component: table, row_selection_enabled: true, row_selection_column: gene_id }

id: arriba_fusions
name: Arriba fusion calls
mode: fusion-detection
description: >-
  Fusion calls Arriba retained, one row per call. The recipe labels each fusion
  from its two partner genes, sums the split reads, discordant mates and local
  coverage into one evidence block, derives a log-scaled support and the
  fraction of local reads that support the call, and splits the contig out of
  each breakpoint so the partners can be read as a chromosome flow.
find: { filename: "*.arriba.fusions.tsv" }
recipe: arriba/fusions.py
fixture: fusions.tsv
renders_as:
  - { id: evidence_dot_plot, component: advanced_viz, kind: dot_plot, roles: {cluster: confidence, gene: fusion, mean_expression: log_support, frac_expressing: support_fraction} }
  # Partner chromosomes as a flow: how a fusion circos reads without an assembly
  # to lay a ring out on. Source contig on the left, partner contig on the right.
  - { id: partner_chrom_sankey, component: advanced_viz, kind: sankey, roles: {steps: [chrom_5p, chrom_3p]} }
  # The two composition bars Arriba's own report leads with: what kind of event
  # each call is, and which transcript feature each breakpoint fell in.
  - { id: type_bars, component: figure, visu_type: bar, dict_kwargs: {x: fusion_type, y: supporting_reads, color: confidence} }
  - { id: site_bars, component: figure, visu_type: bar, dict_kwargs: {x: site_5p, y: supporting_reads, color: site_3p} }
  - { id: type_frame_bars, component: figure, visu_type: bar, dict_kwargs: {x: fusion_type, y: supporting_reads, color: reading_frame} }
  - { component: card, column: supporting_reads, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: fusion, aggregation: nunique, secondary_layout: top_n, breakdown_col: confidence, top_n_count: 3 }
  - { component: card, column: split_reads, aggregation: sum, secondary_layout: donut, breakdown_col: fusion_type }
  - { component: card, column: support_fraction, aggregation: average, secondary_layout: histogram }
  - { component: table, row_selection_enabled: true, row_selection_column: fusion }

id: ataqv_chromosome_counts
name: Reads per reference sequence
mode: qc/read_distribution
description: >-
  How each library's reads are spread over the reference sequences ataqv
  counted. One sequence carrying a disproportionate share, or a library whose
  profile does not match its peers, shows up here before any peak is called.
find:
  path_glob: "**/*.ataqv.json"
recipe: ataqv/chromosome_counts.py
fixture: chromosome_counts.tsv
renders_as:
  - { id: read_distribution, component: advanced_viz, kind: dot_plot, roles: {cluster: sample, gene: chromosome, mean_expression: log10_read_count, frac_expressing: fraction_of_reads} }
  - { component: figure, visu_type: bar, dict_kwargs: {x: chromosome, y: fraction_of_reads, color: sample, title: Share of reads per reference sequence} }
  - { component: card, column: read_count, aggregation: sum, secondary_layout: top_n, breakdown_col: chromosome, top_n_count: 3 }
  - { component: card, column: fraction_of_reads, aggregation: max, secondary_layout: threshold, threshold_value: 0.12, threshold_direction: max, threshold_warn: 0.15 }
  - { component: card, column: fraction_of_reads, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: table }

id: ataqv_metrics
name: ATAC quality metrics
mode: qc/library
description: >-
  One row per ATAC library: TSS enrichment, the share of high-quality autosomal
  alignments that fall inside peaks, mitochondrial and duplicate fractions, and
  the peak statistics ataqv computed. These are the numbers an ATAC library is
  accepted or rejected on, and MultiQC has no module that reports them.
find:
  path_glob: "**/*.ataqv.json"
recipe: ataqv/metrics.py
fixture: metrics.tsv
renders_as:
  # Signal (TSS enrichment) against specificity (reads inside peaks): the two
  # axes an ATAC library is placed on.
  - { component: figure, visu_type: scatter, dict_kwargs: {x: tss_enrichment, y: hqaa_overlapping_peaks_percent, color: sample, size: total_peaks, title: TSS enrichment against reads in peaks} }
  # Signal, then yield, then the two ways an ATAC library wastes reads.
  - { component: card, column: tss_enrichment, aggregation: average, secondary_layout: gauge, coverage_max: 10.0 }
  - { component: card, column: total_peaks, aggregation: sum, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: card, column: mitochondrial_fraction, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: hqaa_overlapping_peaks_percent, aggregation: average, secondary_layout: threshold, threshold_value: 20.0, threshold_direction: min, threshold_warn: 10.0 }
  - { component: card, column: duplicate_fraction, aggregation: average, secondary_layout: histogram }
  - { component: card, column: median_fragment_length, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: table, row_selection_enabled: true, row_selection_column: sample }

id: bambu_counts_gene
name: Gene-level quantification
mode: quantification/gene
description: >-
  Bambu gene-level read counts, the top 50 genes by total count across
  samples, features x samples.
find: { path_glob: "**/bambu/counts_gene.txt" }
recipe: bambu/counts_gene.py
fixture: counts_gene.tsv
renders_as:
  - { id: top_expressed_genes_heatmap, component: advanced_viz, kind: complex_heatmap, roles: {index: gene_id} }
  - { component: card, column: gene_id, aggregation: nunique, secondary_layout: top_n, breakdown_col: gene_biotype, top_n_count: 3 }
  - { component: card, column: gene_biotype, aggregation: nunique, secondary_layout: donut, breakdown_col: gene_biotype }
  - { component: table }

id: bambu_counts_gene_long
name: Gene counts per sample
mode: quantification/gene-long
description: >-
  Bambu gene counts melted to one row per sample and gene, with CPM and
  log2(CPM + 1) normalised against the full library. The long shape is what a
  sample filter can reach: the wide matrix next to it carries no sample column.
find: { path_glob: "**/bambu/counts_gene.txt" }
recipe: bambu/counts_gene_long.py
fixture: counts_gene_long.tsv
renders_as:
  - { component: figure, visu_type: box, dict_kwargs: {x: sample, y: log_cpm, color: condition, title: Expression distribution per library} }
  - { component: card, column: log_cpm, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: gene_id, aggregation: nunique, secondary_layout: top_n, breakdown_col: gene_biotype, top_n_count: 3 }
  - { component: card, column: count, aggregation: sum, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: card, column: gene_biotype, aggregation: nunique, secondary_layout: donut, breakdown_col: gene_biotype }
  - { component: card, column: cpm, aggregation: max, secondary_layout: top_n, breakdown_col: condition, top_n_count: 2 }
  - { component: table, page_size: 25 }

id: bambu_counts_transcript
name: Transcript-level quantification
mode: quantification/transcript
description: >-
  Bambu transcript-level read counts, the top 50 transcripts by total count
  across samples, features x samples.
find: { path_glob: "**/bambu/counts_transcript.txt" }
recipe: bambu/counts_transcript.py
fixture: counts_transcript.tsv
renders_as:
  - { id: top_expressed_transcripts_heatmap, component: advanced_viz, kind: complex_heatmap, roles: {index: transcript_id} }
  - { component: card, column: transcript_id, aggregation: nunique, secondary_layout: top_n, breakdown_col: gene_id, top_n_count: 3 }
  - { component: table }

id: bambu_counts_transcript_long
name: Transcript counts per sample
mode: quantification/transcript-long
description: >-
  Bambu transcript counts melted to one row per sample and transcript, with
