recipe: bambu/counts_transcript_long.py
fixture: counts_transcript_long.tsv
renders_as:
  - { component: figure, visu_type: box, dict_kwargs: {x: sample, y: log_cpm, color: condition, title: Isoform expression distribution per library} }
  - { component: card, column: log_cpm, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: transcript_id, aggregation: nunique, secondary_layout: top_n, breakdown_col: gene_biotype, top_n_count: 3 }
  - { component: card, column: gene_id, aggregation: nunique, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: card, column: count, aggregation: sum, secondary_layout: donut, breakdown_col: condition }
  - { component: table, page_size: 25 }

id: bambu_sample_correlation
name: Sample correlation matrix
mode: exploratory/correlation
description: >-
  Square sample-by-sample Spearman correlation of log-CPM gene expression: the
  plot that shows a swapped label or a replicate that did not replicate, one
  row and one column per sample.
find: { path_glob: "**/bambu/counts_gene.txt" }
recipe: bambu/sample_correlation.py
fixture: sample_correlation.tsv
renders_as:
  - { id: correlation_heatmap, component: advanced_viz, kind: complex_heatmap, roles: {index: sample_id} }
  - { component: card, column: mean_correlation, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: sample_id, aggregation: nunique, secondary_layout: donut, breakdown_col: condition }
  - { component: table }

id: bambu_sample_pca
name: Sample structure and library readings
mode: exploratory/pca
description: >-
  One row per sample: the first three principal components of the log-CPM gene
  matrix, restricted to the 500 most variable genes the way DESeq2 plotPCA
  does, next to the library size, the number of genes detected and the share of
  the library its 50 top genes take.
find: { path_glob: "**/bambu/counts_gene.txt" }
recipe: bambu/sample_pca.py
fixture: sample_pca.tsv
renders_as:
  - { id: pca, component: advanced_viz, kind: embedding, roles: {sample_id: sample_id, dim_1: dim_1, dim_2: dim_2, dim_3: dim_3, color: condition} }
  - { id: depth_vs_complexity, component: advanced_viz, kind: scatter_xy, roles: {x: total_counts, y: n_genes_detected, label: sample_id, color: condition, size: top50_share_pct} }
  - { component: figure, visu_type: bar, dict_kwargs: {x: sample_id, y: total_counts, color: condition, title: Reads assigned per library} }
  - { component: card, column: total_counts, aggregation: sum, secondary_layout: top_n, breakdown_col: sample_id, top_n_count: 3 }
  - { component: card, column: n_genes_detected, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: pct_protein_coding, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: top50_share_pct, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: sample_id, aggregation: nunique, secondary_layout: donut, breakdown_col: condition }
  - { component: table }

id: bcftools_stats_summary
name: Per-caller variant counts
mode: stats-summary
description: >-
  Per-sample, per-caller variant record counts (SNPs, indels, multiallelic
  sites) from `bcftools stats`. Pipeline-agnostic: any workflow that runs
  `bcftools stats` per caller per sample, with the caller and sample in the
  path rather than in the file, lands in the same collection.
find:
  path_glob: "**/*.bcftools_stats.txt"
recipe: bcftools/stats_summary.py
fixture: stats_summary.tsv
renders_as:
  - { component: figure, visu_type: bar, dict_kwargs: {x: caller, y: n_snps, color: sample, barmode: group} }
  - { component: card, column: n_snps, aggregation: sum, secondary_layout: top_n, breakdown_col: caller, top_n_count: 3 }
  - { component: card, column: n_indels, aggregation: sum, secondary_layout: top_n, breakdown_col: caller, top_n_count: 3 }
  - { component: card, column: n_multiallelic_sites, aggregation: sum, secondary_layout: donut, breakdown_col: caller }
  - { id: caller_yield_dotplot, component: advanced_viz, kind: dot_plot, roles: {cluster: sample, gene: caller, mean_expression: log10_n_records, frac_expressing: snp_fraction} }
  - { component: table }

