  - { component: card, column: f1, aggregation: max, aggregations: [box_plot_stats], secondary_layout: box_plot } # best F1
  - { component: table }
  # Metric cards and the row-level table behind them: the readings the
  # nf-core dashboards were already computing off this output by hand.
  - { component: card, column: label, aggregation: nunique, secondary_layout: donut, breakdown_col: caller, top_n_count: 3 }
  - { component: card, column: f1, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: precision, aggregation: average, secondary_layout: gauge, coverage_max: 1 }
  - { component: card, column: recall, aggregation: median, secondary_layout: threshold, threshold_value: 0.9, threshold_direction: min, threshold_warn: 0.8 }
  - { component: card, column: fp, aggregation: sum, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: fn, aggregation: sum, secondary_layout: histogram }
  - { component: card, column: f1, aggregation: max, aggregations: [min, median, average, max], secondary_layout: grid }

id: salmon_gene_expression
name: Gene expression (long)
mode: expression/long
description: >-
  The merged Salmon TPMs unpivoted to one row per gene and sample, restricted to
  the genes expressed in at least one sample, with the sample's condition
  attached. The shape a gene explorer filters and groups on.
find: { path_glob: "**/salmon.merged.gene_tpm.tsv" }
recipe: salmon/gene_expression_long.py
fixture: gene_expression.tsv
renders_as:
  - { component: figure, visu_type: box, dict_kwargs: {x: group, y: log2_tpm, color: group} }
  - { component: card, column: tpm, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: gene_name, aggregation: nunique, secondary_layout: donut, breakdown_col: group }
  - { component: interactive, interactive_type: MultiSelect, column_name: gene_name }
  - { component: table, row_selection_enabled: true, row_selection_column: gene_name }
  # Metric cards and the row-level table behind them: the readings the
  # nf-core dashboards were already computing off this output by hand.
  - { component: card, column: sample, aggregation: nunique, secondary_layout: top_n, breakdown_col: group, top_n_count: 4 }
  - { component: card, column: log2_tpm, aggregation: average, secondary_layout: histogram }

id: salmon_sample_pca
name: Sample overview
mode: expression/pca
description: >-
  One row per sample: principal components of the log2(TPM + 1) matrix over its
  most variable genes, plus how many genes the sample detects and expresses and
  the median TPM of the genes it detects.
find: { path_glob: "**/salmon.merged.gene_tpm.tsv" }
recipe: salmon/sample_pca.py
fixture: sample_pca.tsv
renders_as:
  - { id: pca, component: advanced_viz, kind: embedding, roles: {sample_id: sample_id, dim_1: dim_1, dim_2: dim_2, color: group} }
  - { component: card, column: sample_id, aggregation: nunique, secondary_layout: donut, breakdown_col: group }
  - { component: card, column: median_tpm, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  # A library that expresses far fewer genes than its peers is the classic
  # under-sequenced / degraded sample; 10k is the usual floor for a bulk
  # human RNA-seq library, and the dashboard tile can retune it per run.
  - { component: card, column: genes_expressed, aggregation: average, secondary_layout: threshold, threshold_value: 10000, threshold_direction: min, threshold_warn: 8000 }
  - { component: card, column: genes_detected, aggregation: average, secondary_layout: histogram }
  - { component: table }
  # Metric cards and the row-level table behind them: the readings the
  # nf-core dashboards were already computing off this output by hand.
  - { component: card, column: sample_id, aggregation: nunique, secondary_layout: top_n, breakdown_col: group, top_n_count: 4 }
  - { component: card, column: genes_detected, aggregation: average, secondary_layout: gauge, coverage_max: 30000 }

id: samtools_stats_sections
name: Alignment distributions
mode: alignment/distributions
description: >-
  The distribution blocks of a samtools stats report, which MultiQC never
  surfaces: the read-length histogram (RL), the coverage-depth histogram
  (COV), the indel-length spectrum (ID) and, for paired data, the insert-size
  distribution (IS), with the SN summary block on one row per sample beside
  them. Each section has its own value column, so three profile tiles read the
  same collection without a filter between them.
# `*.bam.stats` rather than `*.stats`: the latter also matches the
# `*flagstat.stats` that `flagstat.yaml` owns, and a file reached by two globs
# is recognised as two different outputs.
find:
  path_glob: "**/*.bam.stats"
  path_glob_alt:
    - "**/samtools_stats/*.stats"
    - "**/samtools/*.stats"
recipe: samtools/stats_sections.py
fixture: stats_sections.tsv
renders_as:
  - { id: read_length_profile, component: advanced_viz, kind: profile, roles: {series: series, x: bin, y: n_reads} }
  - { id: coverage_distribution, component: advanced_viz, kind: profile, roles: {series: series, x: bin, y: n_bases} }
  - { id: indel_spectrum, component: advanced_viz, kind: profile, roles: {series: series, x: bin, y: n_indels} }
  - { component: card, column: reads_mapped_pct, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: identity_pct, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: average_length, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: maximum_length, aggregation: max, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: card, column: supplementary_alignments, aggregation: sum, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: card, column: average_quality, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: reads_mapped, aggregation: sum, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: table, page_size: 25 }

id: seacr_peaks
name: Peak calls
mode: peaks/seacr
description: >-
  Every SEACR region of every sample in one table, with the total and the
  maximum fragment coverage over the region, its width and where inside it the
  maximum was reached.
# SEACR reports no p-value and no fold enrichment, so significance is read off
# the coverage itself: `log10_total_signal` is the height of the genome track
# and `signal_density` the coverage per base.
find:
  path_glob: "**/*.seacr.peaks.*.bed"
recipe: seacr/peaks.py
fixture: peaks.tsv
renders_as:
  # Where the signal is, then how the two coverage measures relate and how wide
  # the calls are behind them.
  - { id: seacr_peak_signal, component: advanced_viz, kind: manhattan, roles: {chr: chr, pos: summit, score: log10_total_signal} }
  # The same three roles on a chromosome-aware locus axis, plus `end` so a call
  # is drawn as the interval it is rather than as a point at its summit. The
  # coverage track binds the same columns through the Plotly renderer, which is
  # what a tab falls back to when the GenomeSpy canvas is unavailable.
  - { id: seacr_peak_track, component: advanced_viz, kind: genome_view, roles: {chr: chr, pos: start, score: log10_total_signal, feature: peak_id, end: end} }
  - { id: seacr_peak_coverage, component: advanced_viz, kind: coverage_track, roles: {chromosome: chr, position: start, value: log10_total_signal, end: end, sample: sample} }
  - { id: seacr_signal_scatter, component: figure, visu_type: scatter, dict_kwargs: {x: total_signal, y: max_signal, color: sample, title: Total against maximum signal} }
  - { id: seacr_width_hist, component: figure, visu_type: histogram, dict_kwargs: {x: width, color: sample, title: Peak width distribution} }
  # How many regions and where they concentrate, then the spread of width,
  # total coverage and coverage per base behind that count.
  - { component: card, column: peak_id, aggregation: count, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: card, column: width, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: total_signal, aggregation: sum, secondary_layout: histogram }
  - { component: card, column: signal_density, aggregation: average, secondary_layout: histogram }
  - { component: table, row_selection_enabled: true, row_selection_column: peak_id }

id: sidle_reconstructed
name: Reconstructed features
mode: reconstructed
description: >-
  The cross-region reconstructed feature table melted to one row per feature
  and sample, with the Greengenes lineage split into rank columns. This is the
  community a multi-region run actually resolves, as opposed to the per-primer
  tables it starts from.
find:
  path_glob: "**/sidle/reconstructed/reconstructed_merged.tsv"
recipe: sidle/reconstructed.py
fixture: reconstructed.tsv
renders_as:
  # Wide per-rank columns, so the nested view is a sunburst; `stacked_taxonomy`
  # needs the single long rank column this table lacks.
  - { id: reconstructed_sunburst, component: advanced_viz, kind: sunburst, roles: {abundance: count} }
  - { component: figure, visu_type: bar, dict_kwargs: {x: sample, y: count, color: Phylum, title: Composition by phylum} }
  - { component: figure, visu_type: bar, dict_kwargs: {x: sample, y: count, color: Genus, title: Composition by genus} }
  # How much was reconstructed, from how many samples, across how many phyla.
  - { component: card, column: feature_id, aggregation: nunique, secondary_layout: top_n, breakdown_col: Phylum, top_n_count: 3 }
  - { component: card, column: sample, aggregation: nunique, secondary_layout: top_n, breakdown_col: sample, top_n_count: 3 }
  - { component: card, column: Phylum, aggregation: nunique, secondary_layout: composition, breakdown_col: Phylum }
  - { component: interactive, interactive_type: MultiSelect, column_name: Phylum }
  - { component: table }

id: sidle_reconstruction_qc
name: Reconstruction confidence
mode: reconstruction-summary
description: >-
  How many amplified regions mapped to each reconstructed feature and how much
  kmer support stood behind them. A feature carried by one region is a
  different claim from one carried by all of them, and this is the table that
  separates the two.
find:
  path_glob: "**/sidle/**/reconstruction_summary/metadata.tsv"
recipe: sidle/reconstruction_qc.py
fixture: reconstruction_qc.tsv
renders_as:
  # Support against coverage: the two axes that qualify a reconstructed feature.
  - { id: reconstruction_support, component: advanced_viz, kind: scatter_xy, roles: {x: num_regions, y: total_kmers_mapped, size: mean_kmer_per_region, label: feature_id} }
  - { component: figure, visu_type: histogram, dict_kwargs: {x: num_regions, title: Features by regions mapped} }
  - { component: card, column: num_regions, aggregation: average, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: total_kmers_mapped, aggregation: median, secondary_layout: histogram }
  - { component: card, column: mean_kmer_per_region, aggregation: average, secondary_layout: histogram }
  - { component: table }

id: sompy_summary
name: som.py benchmark summary
mode: benchmark-summary
description: >-
  Somatic small-variant accuracy from som.py: precision/recall/F1 per callset
  with binomial confidence intervals. `caller` is the tool that made the calls,
  `label` the callset's samplesheet id and `truth_set` the truth set.
find: { path_glob: "**/summary/tables/sompy/sompy.summary.csv" }
recipe: sompy/summary.py
fixture: summary.tsv
renders_as:
  - { id: pr_scatter, component: advanced_viz, kind: pr_benchmark, roles: {label: caller, recall: recall, precision: precision, f1: f1} } # precision-recall benchmark
  - { id: confusion, component: advanced_viz, kind: confusion_matrix, roles: {label: caller, tp: tp, fp: fp, fn: fn} } # TP/FP/FN matrix
  - { id: precision_ci, component: advanced_viz, kind: metric_ci_bars, roles: {label: caller, value: precision, lower: precision_lower, upper: precision_upper} } # precision ± 95% CI
  - { id: recall_ci, component: advanced_viz, kind: metric_ci_bars, roles: {label: caller, value: recall, lower: recall_lower, upper: recall_upper} } # recall ± 95% CI
  - { component: figure, visu_type: bar, dict_kwargs: {x: caller, y: f1} } # f1 by caller
  - { component: card, column: f1, aggregation: max, aggregations: [box_plot_stats], secondary_layout: box_plot } # best F1
  - { component: table }
  # Metric cards and the row-level table behind them: the readings the
  # nf-core dashboards were already computing off this output by hand.
  - { component: card, column: caller, aggregation: nunique, secondary_layout: donut, breakdown_col: variant_type, top_n_count: 3 }
  - { component: card, column: f1, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: recall, aggregation: average, secondary_layout: gauge, coverage_max: 1 }
  - { component: card, column: precision, aggregation: median, secondary_layout: threshold, threshold_value: 0.5, threshold_direction: min, threshold_warn: 0.25 }
  - { component: card, column: fp, aggregation: sum, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: fn, aggregation: sum, secondary_layout: histogram }
  - { component: card, column: f1, aggregation: max, aggregations: [min, median, average, max], secondary_layout: grid }

id: starfusion_fusions
name: STAR-Fusion calls
mode: fusion-detection
description: >-
  Fusion predictions from the abridged STAR-Fusion table, one row per call. The
  recipe strips the Ensembl id off each partner gene, sums junction reads and
  spanning fragments into one evidence count, and derives a log-scaled FFPM plus
  the fraction of the evidence that crosses the junction itself.
find: { filename: "*.starfusion.abridged.tsv" }
recipe: starfusion/fusions.py
fixture: fusions.tsv
renders_as:
  - { id: evidence_dot_plot, component: advanced_viz, kind: dot_plot, roles: {cluster: splice_type, gene: fusion, mean_expression: log_ffpm, frac_expressing: junction_fraction} }
  - { component: figure, visu_type: bar, dict_kwargs: {x: splice_type, y: supporting_reads, color: large_anchor_support} }
  - { component: card, column: ffpm, aggregation: median, aggregations: [box_plot_stats], secondary_layout: box_plot }
  - { component: card, column: fusion, aggregation: nunique, secondary_layout: top_n, breakdown_col: splice_type, top_n_count: 3 }
  - { component: card, column: supporting_reads, aggregation: sum, secondary_layout: donut, breakdown_col: large_anchor_support }
  - { component: card, column: junction_fraction, aggregation: average, secondary_layout: histogram }
  - { component: table, row_selection_enabled: true, row_selection_column: fusion }

id: truvari_summary
name: Truvari SV summary
mode: benchmark-summary
description: >-
  Structural-variant accuracy from Truvari (precision/recall/F1). Optional: not
  produced by the public megatest; recipe uses tolerant column matching;
  `caller` and `truth_set` come from the pipeline's `Caller` and `File` columns.
find: { path_glob: "**/summary/tables/truvari/truvari.summary.csv" }
recipe: truvari/summary.py
